import{_ as s,o as t,c as o,a0 as n}from"./chunks/framework.ChlVJx0I.js";const a="/pi-extensions/assets/compress-status.DLN2ruRd.png",m=JSON.parse('{"title":"compress extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/compress.md","filePath":"extensions/compress.md","lastUpdated":1789775493000}'),i={name:"extensions/compress.md"};function r(d,e,l,h,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="compress-extension" tabindex="-1">compress extension <a class="header-anchor" href="#compress-extension" aria-label="Permalink to &quot;compress extension&quot;">​</a></h1><p>Compresses finished turns out of outgoing LLM requests without touching the session file. A turn that falls out of the keep window is replaced in every outgoing request by one short synthetic user message carrying a compressed form of the turn. The full original messages stay in the session file, and each compressed span is persisted as a <code>compress-span</code> custom session entry (<a href="/pi-extensions/adr/0015-compression-is-a-request-time-view.html">ADR 0015</a>).</p><p>Compression is opt-in: the extension does nothing until a compression model is set with <code>/compression-model</code>.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The status bar line the extension adds once spans exist: the span count and the tokens saved, in dim text.</p><p><img src="'+a+`" alt="compress status line"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Keep window.</strong> The last <code>keepTurns</code> finished turns, plus the turn in progress, always go out raw. Every older finished turn is a span.</li><li><strong>Prewarm.</strong> After each turn ends, the extension compresses every uncached span that is at least <code>minSpanTokens</code> tokens, one call at a time in the background. Small spans never earn a call.</li><li><strong>The form.</strong> One call to the compression model: the turn serialized with pi&#39;s role labels, every tool result cut to head + tail (2000 characters total, so a failure&#39;s error line at the tail survives), and a prompt that keeps user instructions verbatim and quotes error strings exactly as shown. The form is capped at <code>spanCapTokens</code>; the request&#39;s token budget is the cap plus a 1024-token thinking reserve, so a thinking model can reason before writing the note, and the form is trimmed back to the cap afterwards.</li><li><strong>The swap.</strong> The next outgoing request replaces each cached span with one user message: a fixed lossy-view frame, then the form. The extension rewrites a request only when it can reconcile pi&#39;s exact message list from the session entries: every message must match in order, and only failed assistant messages (the ones pi removes from its state while retrying a call) may be absent. Anything else it cannot reproduce goes out untouched, and the check re-runs on every request.</li><li><strong>Failure.</strong> A failed compression call leaves the span raw and retries after the next turn, with one warning per span. A span that fails three calls in a row stops earning calls and stays raw for the session; changing the compression model resets the counter. A span whose serialized input does not fit the compression model&#39;s context window (input plus the cap plus a 1k-token margin) never earns a call.</li><li><strong>Startup retry.</strong> If the configured model is not in the registry at session start, compression starts off and the resolution re-runs after each turn. A local provider registers its models on demand, so a model that is still loading or asleep at start resolves later in the session. When it resolves, compression turns on from that turn and the failure counters restart.</li><li><strong>Restart.</strong> Spans already have their persisted form, so no compression is re-run after a restart.</li><li><strong>Usage.</strong> Each compression call is a normal LLM event: its usage is in the span entry and counts in the Usage report under the compression model.</li></ul><h2 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h2><p><code>/compression-model [off | provider/model-id]</code></p><ul><li>No args: shows the current model, span count, and tokens saved, then opens a model picker (an <code>off</code> entry disables).</li><li><code>off</code>: disables compression and persists it.</li><li><code>provider/model-id</code>: sets the model directly. A model that is missing or has no configured auth is rejected.</li></ul><p>The choice persists to the project <code>.pi/settings.json</code> when that file exists, else to the global settings file.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <code>compress</code> section of <code>settings.json</code>. Project <code>&lt;cwd&gt;/.pi/settings.json</code> overrides global, key by key.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Turn the extension on or off.</td></tr><tr><td><code>model</code></td><td><code>&quot;provider/model-id&quot;</code> or <code>null</code></td><td><code>null</code></td><td>The compression model. <code>null</code>: compression off.</td></tr><tr><td><code>keepTurns</code></td><td><code>number</code> ≥ 0</td><td><code>2</code></td><td>Recent finished turns that always go out raw.</td></tr><tr><td><code>spanCapTokens</code></td><td><code>number</code> &gt; 0</td><td><code>500</code></td><td>Cap for one compressed form, in tokens.</td></tr><tr><td><code>minSpanTokens</code></td><td><code>number</code> &gt; 0</td><td><code>1000</code></td><td>A span smaller than this never earns a compression call.</td></tr></tbody></table><p>Example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;compress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;anthropic/claude-haiku&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;keepTurns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;spanCapTokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;minSpanTokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A malformed value falls back to its default and is reported with one startup notification.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>While spans are compressed, the status line shows the span count and the tokens saved, for example <code>compress: 3 spans, 12.4k saved</code>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>Seam.</strong> The decision logic lives in <code>core.ts</code>, which is engine-free and fully tested with an injected token estimator and serializer: given the turns and the cache, it produces the outgoing message list and the compression jobs. <code>serializer.ts</code> turns one turn into the compression model&#39;s input. <code>settings.ts</code> reads and writes the settings section. <code>runner.ts</code> runs one job through pi&#39;s model registry as a fresh conversation (new session ID, no cache retention). <code>index.ts</code> is the thin pi wiring.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Recompressing a span when the compression model changes (the first form stays), mid-conversation compaction of the keep window, and per-tool output shrinking.</p>`,24)])])}const g=s(i,[["render",r]]);export{m as __pageData,g as default};
